# FE v119-57 / v120-esm-g (06/09/2026): (1) wizard "Thêm brand mới" bước Hoàn tất có "🔎 Quét thử nguồn này (≤15 bài)" — chọn 1 nguồn của brand → openBackfill(url, tên,
# {numPosts:15, range:'7d'}) → manualScan mode backfill nhận sourceUrl + numPosts (backend đã hỗ trợ từ LỆNH #19) → xem chất lượng lead của riêng nguồn trước khi để tự động;
# (2) openBackfill nhận opts {numPosts, range} (tiêu đề + body.numPosts + rangeText); (3) live.js đọc content_stats/{brand} (CF statsOnLead — LỆNH #36) → D.contentStats;
# (4) card "📈 Hiệu quả nội dung" (Content Studio) ưu tiên counter máy chủ (chính xác mọi quy mô), chưa có counter → đếm lead đã nạp như v119-55; (5) smoke +3 check.
# Dùng: python3 fe57.py <root> iife|esm
import sys, os
root, mode = sys.argv[1], sys.argv[2]
def load(rel):
    p = os.path.join(root, rel); return p, open(p, encoding='utf-8').read()
def save(p, s): open(p, 'w', encoding='utf-8').write(s)
def R(s, a, b, n=1):
    assert s.count(a) == n, (a[:90], s.count(a)); return s.replace(a, b)

# ---------- 70-shell-tools: openBackfill(sourceUrl, sourceName, opts) ----------
p, s = load('src/app/70-shell-tools.js')
s = R(s, "  function openBackfill(sourceUrl, sourceName){\n    const fn=(window.SL_CONFIG&&window.SL_CONFIG.MANUAL_SCAN_URL)||'';",
       "  function openBackfill(sourceUrl, sourceName, opts){\n    opts=opts||{}; const quickN=Math.max(0,Math.min(100,Number(opts.numPosts)||0)); // v119-57: quét thử riêng nguồn (wizard) — giới hạn số bài + khoảng chọn sẵn\n    const fn=(window.SL_CONFIG&&window.SL_CONFIG.MANUAL_SCAN_URL)||'';")
s = R(s, "        <div class=\"sub\" style=\"margin-top:4px\">Phạm vi: <b>${target}</b></div></div>\n        <button class=\"close\" id=\"bfClose\">${SLI.x}</button></div>",
       "        <div class=\"sub\" style=\"margin-top:4px\">Phạm vi: <b>${target}</b>${quickN?' · <b>quét thử</b> tối đa '+quickN+' bài mới nhất':''}</div></div>\n        <button class=\"close\" id=\"bfClose\">${SLI.x}</button></div>")
s = R(s, "${ranges.map(([k,l])=>`<button data-range=\"${k}\" class=\"${k==='7d'?'active':''}\">${l}</button>`).join('')}",
       "${ranges.map(([k,l])=>`<button data-range=\"${k}\" class=\"${k===(opts.range||'7d')?'active':''}\">${l}</button>`).join('')}")
s = R(s, "    let range='7d';\n    const seg=modal.querySelector('#bfSeg'), custom=modal.querySelector('#bfCustom');",
       "    let range=opts.range||'7d';\n    const seg=modal.querySelector('#bfSeg'), custom=modal.querySelector('#bfCustom');")
s = R(s, "      if(sourceUrl) body.sourceUrl=sourceUrl;\n      if(!fn){ toast('Demo - cấu hình MANUAL_SCAN_URL để quét thật.'); closeModal(); return; }",
       "      if(sourceUrl) body.sourceUrl=sourceUrl;\n      if(quickN){ body.numPosts=quickN; rangeText+=' · quét thử '+quickN+' bài'; } // v119-57: backend scanAll(opts.numPosts) → fetchPosts numPosts\n      if(!fn){ toast('Demo - cấu hình MANUAL_SCAN_URL để quét thật.'); closeModal(); return; }")
save(p, s)

# ---------- 87-brand-wizard: bước Hoàn tất — quét thử 1 nguồn ----------
p, s = load('src/app/87-brand-wizard.js')
if mode == 'esm':
    s = R(s, "import { fold } from './70-shell-tools.js';", "import { fold, openBackfill } from './70-shell-tools.js';")
s = R(s, "      <div class=\"wz-actions\">\n        ${roleCanScan()?`<button class=\"btn btn-primary btn-sm\" id=\"wzScan\">${SLI.search} Quét ngay (mọi nguồn)</button>`:''}",
       "      ${(roleCanScan()&&srcAll.length)?`<div class=\"wz-try\"><span class=\"wz-small\">Quét thử riêng 1 nguồn (7 ngày gần nhất, tối đa 15 bài) để xem chất lượng lead trước khi để tự động:</span>\n        <select class=\"acs-in\" id=\"wzTrySrc\">${srcAll.map(s=>`<option value=\"${esc(s.url||'')}\">${esc(s.name||s.url||s.id||'')}</option>`).join('')}</select>\n        <button class=\"btn btn-soft btn-sm\" id=\"wzTryScan\">🔎 Quét thử nguồn này</button></div>`:''}\n      <div class=\"wz-actions\">\n        ${roleCanScan()?`<button class=\"btn btn-primary btn-sm\" id=\"wzScan\">${SLI.search} Quét ngay (mọi nguồn)</button>`:''}")
s = R(s, "    const sc=m.querySelector('#wzScan'); if(sc) sc.addEventListener('click',()=>{ wzClose(); const b=document.getElementById('scanBtn'); if(b) b.click(); else toast('Không thấy nút Quét ngay.'); });",
       "    const sc=m.querySelector('#wzScan'); if(sc) sc.addEventListener('click',()=>{ wzClose(); const b=document.getElementById('scanBtn'); if(b) b.click(); else toast('Không thấy nút Quét ngay.'); });\n    // v119-57: quét thử RIÊNG 1 nguồn của brand (backfill 7 ngày, numPosts 15) — manualScan nhận sourceUrl+numPosts (LỆNH #19); wizard đóng trước vì cùng dùng #modal\n    const ts=m.querySelector('#wzTryScan'); if(ts) ts.addEventListener('click',()=>{ const sel=m.querySelector('#wzTrySrc'); const url=sel&&sel.value; const nm=sel&&sel.options[sel.selectedIndex]?sel.options[sel.selectedIndex].textContent:''; if(!url){ toast('Nguồn chưa có link group.'); return; } wzClose(); openBackfill(url,nm,{numPosts:15,range:'7d'}); });")
save(p, s)

# ---------- CSS ----------
