# ---------- live.js: content_stats ----------
p, s = load('assets/js/live.js')
s = R(s, "  let sysStatus=null; // v119-50:", "  let contentStats={}; // v119-57: content_stats/{brand} — counter hiệu quả nội dung (sent/rep theo mode/parent/style/cta/variant) do CF statsOnLead cộng dồn (LỆNH #36) → card Content Studio chính xác mọi quy mô\n  let sysStatus=null; // v119-50:")
s = R(s, "d.sysStatus=sysStatus; // v119-50 trạng thái BrightData", "d.sysStatus=sysStatus; d.contentStats=contentStats; // v119-57 counter hiệu quả nội dung · v119-50 trạng thái BrightData")
s = R(s, "dailyStats=[]; dailyStatsErr=''; sysStatus=null;", "dailyStats=[]; dailyStatsErr=''; sysStatus=null; contentStats={};")
s = R(s, "        dataUnsub.push(onSnapshot(statsQ, snap=>{ chanOk('outreach_stats'); outreachStats={}; snap.forEach(d=>{ var x=d.data(); if(x.brandCode && x.day===tk) outreachStats[x.brandCode]=x; }); oaRepaint(); }, snapErr('outreach_stats'))); };",
       "        dataUnsub.push(onSnapshot(statsQ, snap=>{ chanOk('outreach_stats'); outreachStats={}; snap.forEach(d=>{ var x=d.data(); if(x.brandCode && x.day===tk) outreachStats[x.brandCode]=x; }); oaRepaint(); }, snapErr('outreach_stats')));\n        // v119-57: content_stats/{brand} — counter cộng dồn hiệu quả nội dung (CF statsOnLead, LỆNH #36). Rules có thể chưa deploy → lỗi chỉ console.warn (KHÔNG banner kênh), card tự rơi về đếm lead đã nạp.\n        var csQ = byBrand ? query(collection(db,'content_stats'), where('brandCode','==',byBrand)) : collection(db,'content_stats');\n        dataUnsub.push(onSnapshot(csQ, snap=>{ contentStats={}; snap.forEach(d=>{ var x=d.data()||{}; contentStats[x.brandCode||d.id]=x; }); oaRepaint(); }, function(e){ console.warn('[SL] content_stats', e&&e.code); })); };")
s = R(s, "      for(var j=0;j<codes.length;j++){ var st=outreachStats[codes[j]]||{}; s+='|'+codes[j]+'='+(st.react||0)+','+(st.comment||0)+','+(st.friend||0)+','+(st.inbox||0)+','+(st.replied||0); }\n      return s;",
       "      for(var j=0;j<codes.length;j++){ var st=outreachStats[codes[j]]||{}; s+='|'+codes[j]+'='+(st.react||0)+','+(st.comment||0)+','+(st.friend||0)+','+(st.inbox||0)+','+(st.replied||0); }\n      var cc=Object.keys(contentStats||{}).sort(); for(var q=0;q<cc.length;q++){ var ca=(contentStats[cc[q]]||{}).all||{}; s+='|cs:'+cc[q]+'='+(ca.sent||0)+','+(ca.rep||0)+','+(ca.tagged||0); } // v119-57\n      return s;")
save(p, s)

# ---------- 45-outreach: card ưu tiên counter ----------
p, s = load('src/app/45-outreach.js')
s = R(s, "  function csEffData(code) {\n    const all = (D.leads || [])",
       "  // v119-57: counter máy chủ content_stats/{brand} (CF statsOnLead — LỆNH #36: sent = lead có inbox_at, rep = lead đã inbox rồi phản hồi/chuyển Đã phản hồi trở đi) → chính xác mọi quy mô,\n  //   không phụ thuộc cửa sổ lead đã nạp. Khoá value dim đã \"làm sạch\" ở backend: variant → v0..v5 / vx (-1), parent rỗng → none; đổi ngược ở đây để dùng nhãn CS_META_VI.\n  const CS_KEY_BACK = { variant: k => (k === 'vx' ? '-1' : String(k).replace(/^v/, '')), parent: k => (k === 'none' ? '' : k) };\n  function csEffFromCounters(cs) {\n    const all = cs.all || {};\n    const dims = Object.keys(CS_META_VI).map(dim => {\n      const m = (cs[dim] && typeof cs[dim] === 'object') ? cs[dim] : {};\n      const rows = Object.keys(m).map(k => { const o = m[k] || {}; return { k: (CS_KEY_BACK[dim] || (x => x))(k), n: Number(o.sent) || 0, r: Number(o.rep) || 0 }; }).filter(x => x.n > 0)\n        .sort((a, b) => (b.r / b.n) - (a.r / a.n) || b.n - a.n).map(x => ({ label: CS_META_VI[dim][1][x.k] || x.k || '—', n: x.n, r: x.r }));\n      return { dim, title: CS_META_VI[dim][0], rows };\n    });\n    return { total: Number(all.sent) || 0, replied: Number(all.rep) || 0, dims, tagged: Number(all.tagged) || 0, server: true };\n  }\n  function csEffData(code) {\n    const cs = D.contentStats && D.contentStats[code]; if (cs && cs.all && Number(cs.all.sent) > 0) return csEffFromCounters(cs); // counter có số → tin máy chủ; chưa có → đếm lead đã nạp (v119-55)\n    const all = (D.leads || [])")
s = R(s, "    return `<div class=\"cs-preview cs-eff\" id=\"csEff\"><div class=\"cf-k\">📈 Hiệu quả nội dung <span class=\"muted\" style=\"font-weight:400;font-size:11px\">(lead đã nạp trên máy · phản hồi = máy phát hiện hoặc sales chuyển \"Đã phản hồi\" trở đi · mỗi dòng cần ≥30 tin mới đáng tin)</span></div>${body}</div>`;",
       "    return `<div class=\"cs-preview cs-eff\" id=\"csEff\" data-cs-src=\"${e.server ? 'server' : 'local'}\"><div class=\"cf-k\">📈 Hiệu quả nội dung <span class=\"muted\" style=\"font-weight:400;font-size:11px\">(${e.server ? 'máy chủ đếm cộng dồn - chính xác mọi quy mô' : 'lead đã nạp trên máy'} · phản hồi = máy phát hiện hoặc sales chuyển \"Đã phản hồi\" trở đi · mỗi dòng cần ≥30 tin mới đáng tin)</span></div>${body}</div>`;")
save(p, s)

# ---------- smoke: +3 check ----------
p, s = load('tools/smoke.js')
# (1) card đọc counter máy chủ
a = "    (/Chưa có tin inbox/.test(eff0) && eff1 && /Đã inbox 3/.test(eff1.sum) && /phản hồi 2/.test(eff1.sum) && eff1.rows >= 4) ? ok('v119-55: card Hiệu quả nội dung (rỗng → 3 tin/2 phản hồi, bảng theo bài gốc/CTA/biến thể)') : fail('v119-55 card hiệu quả sai: ' + JSON.stringify({ eff0: String(eff0).slice(0, 60), eff1 }));\n"
assert s.count(a) == 1
s = s.replace(a, a + "    /* v119-57: counter máy chủ content_stats (LỆNH #36) → card ưu tiên counter (data-cs-src=server), khoá variant/parent đổi ngược ra nhãn */\n    await page.evaluate(() => { const code = document.querySelector('button[data-oa-content]').dataset.oaContent; window.SL_DATA.contentStats = { [code]: { brandCode: code, all: { sent: 40, rep: 8, tagged: 55 }, mode: { ai: { sent: 30, rep: 7 }, reply: { sent: 10, rep: 1 } }, variant: { v0: { sent: 20, rep: 5 }, vx: { sent: 20, rep: 3 } }, parent: { none: { sent: 40, rep: 8 } }, cta: { brand: { sent: 40, rep: 8 } }, style: { direct: { sent: 40, rep: 8 } } } }; });\n    await page.click('button[data-oa-content]'); await page.waitForTimeout(300);\n    const eff2 = await page.evaluate(() => { const e = document.getElementById('csEff'); return e ? { src: e.dataset.csSrc, sum: (e.querySelector('.cs-eff-sum') || {}).textContent || '', rows: e.querySelectorAll('.cs-eff-t tbody tr').length, txt: e.textContent } : null; });\n    await page.evaluate(() => { const c = document.getElementById('csCancel'); if (c) c.click(); delete window.SL_DATA.contentStats; }); await page.waitForTimeout(200);\n    (eff2 && eff2.src === 'server' && /Đã inbox 40/.test(eff2.sum) && /phản hồi 8/.test(eff2.sum) && eff2.rows === 4 && /\\(không xoay\\)/.test(eff2.txt) && /Đồng cảm/.test(eff2.txt) && /máy chủ đếm/.test(eff2.txt)) ? ok('v119-57: card Hiệu quả nội dung đọc counter máy chủ (40 tin/8 phản hồi · 2 bảng · nhãn biến thể đổi ngược từ v0/vx)') : fail('v119-57 card counter sai: ' + JSON.stringify(eff2 && { src: eff2.src, sum: eff2.sum, rows: eff2.rows }));\n")
# (2) wizard Hoàn tất: ô chọn nguồn + nút quét thử (brand vừa tạo có 1 nguồn)
a = "  (wz7.step === 'done' && wz7.role === 'admin' && wz7.active && wz7.done === 6 && wz7.setup && wz7.scan) ? ok('Wizard: duyệt 1 user làm Quản trị → Hoàn tất 6/6 ✓ + nút Quét ngay + dấu setup') : fail('Hoàn tất sai: ' + JSON.stringify(wz7));\n"
assert s.count(a) == 1
