# (3) resume z15 → tới Hoàn tất → bấm Quét thử → modal Quét ngược quá khứ phạm vi 1 nguồn, quét thử tối đa 15 bài, 7 ngày chọn sẵn
a = "  (rz3.step === 'users' && rz3.cold === 0 && rz3.on === true && rz3.crm) ? ok('Wizard resume: Lưu & tiếp KHÔNG đè ma trận tuỳ chỉnh, không tắt automation, không tách CRM khỏi cấu hình chung') : fail('Resume ghi đè: ' + JSON.stringify(rz3));\n  await page.keyboard.press('Escape'); await page.waitForTimeout(200);\n"
assert s.count(a) == 1
s = s.replace(a, "  (rz3.step === 'users' && rz3.cold === 0 && rz3.on === true && rz3.crm) ? ok('Wizard resume: Lưu & tiếp KHÔNG đè ma trận tuỳ chỉnh, không tắt automation, không tách CRM khỏi cấu hình chung') : fail('Resume ghi đè: ' + JSON.stringify(rz3));\n  await page.evaluate(() => { (window.SL_DATA.sources || []).slice(0, 2).forEach(s => { s.__bakBrand = s.brand; s.brand = 'z15'; }); }); // demo: nguồn không có brand → gán tạm 2 nguồn cho z15 (trả lại sau)\n  await page.click('#wzSkip'); await page.waitForTimeout(300);\n  const rz4 = await page.evaluate(() => { const n = (window.SL_DATA.sources || []).filter(x => (x.brand || '') === 'z15').length; return { step: document.querySelector('.wz-panel').dataset.wzStep, n, opts: document.querySelectorAll('#wzTrySrc option').length, btn: !!document.getElementById('wzTryScan') }; });\n  if (rz4.step === 'done' && rz4.n > 0 && rz4.opts === rz4.n && rz4.btn) { await page.click('#wzTryScan'); await page.waitForTimeout(300);\n    const rz5 = await page.evaluate(() => ({ h: (document.querySelector('#modal h3') || {}).textContent || '', sub: (document.querySelector('#modal .sub') || {}).textContent || '', run: !!document.getElementById('bfRun'), range: (document.querySelector('#bfSeg button.active') || { dataset: {} }).dataset.range, wz: !!document.querySelector('.wz-panel') }));\n    (/Quét ngược quá khứ/.test(rz5.h) && /quét thử/.test(rz5.sub) && /tối đa 15 bài/.test(rz5.sub) && rz5.run && rz5.range === '7d' && !rz5.wz) ? ok('v119-57: Quét thử nguồn này → modal quét ngược phạm vi 1 nguồn · quét thử tối đa 15 bài · 7 ngày chọn sẵn (wizard đã đóng)') : fail('v119-57 modal quét thử sai: ' + JSON.stringify(rz5));\n    await page.click('#bfClose'); await page.waitForTimeout(200);\n  } else { fail('v119-57: Hoàn tất (resume z15) thiếu ô quét thử: ' + JSON.stringify(rz4)); await page.keyboard.press('Escape'); await page.waitForTimeout(200); }\n  await page.evaluate(() => { (window.SL_DATA.sources || []).forEach(s => { if ('__bakBrand' in s) { if (s.__bakBrand === undefined) delete s.brand; else s.brand = s.__bakBrand; delete s.__bakBrand; } }); });\n")
save(p, s)
print('FE57 OK', mode)
